import{_ as i,o as t,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-01-31","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-01-31","date":"2024-01-31T00:00:00.000Z","updated":"2024-02-02T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","代码重构","持久化通知"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.md","lastUpdated":1780460162000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-01-31.md"};function n(r,e,p,s,_,c){return t(),l("div",null,[...e[0]||(e[0]=[a("<p>本次 Ceph RGW 重构会议主要讨论了分布式存储系统中持久化通知的问题、代码冻结计划的调整以及其他议题。</p><ol><li><p><strong>持久化通知问题的讨论</strong>：</p><ul><li>会议指出，在非持久化通知的实现中，存在一个问题，即当消息代理宕机或用户错误配置代理地址时，持久化通知队列会不断增长，事件永久保留。</li><li>现有的解决方案包括引入两个变量：生存时间（TTL）和最大重试次数（Max Retry），默认设置为零，意味着事件将永久保留。</li><li>讨论了是否应该允许用户在创建主题时设置这些值，以及如何处理用户设置与管理员设置之间的优先级关系。</li><li>最终决定通过配置选项来实现，允许用户或存储管理员决定 TTL 和 Max Retry 的值。</li></ul></li><li><p><strong>代码冻结计划的调整</strong>：</p><ul><li>原计划在1月底进行代码冻结，创建 squid 分支。</li><li>经过讨论，决定将代码冻结推迟一周，以便其他组件有更多时间准备。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>讨论了多个分支上的 PR 合并问题，计划在 squid 分支创建后，开始将内容合并到主分支，并在准备就绪后进行回溯合并。</li><li>提及了等待 Neo rados chain 的更新，以便在 gate admin 级别使用站点配置（site config）。</li></ul></li></ol><p>会议决定事项：</p><ul><li>通过配置选项支持 TTL 和 Max Retry 的用户和管理员配置。</li><li>将代码冻结计划推迟一周。</li></ul><p>后续行动计划：</p><ul><li>撰写详细设计文档，并在 Tracker 中记录相关信息。</li><li>继续关注并整合各个 PR，确保在代码冻结前所有功能准备就绪。</li><li>在 squid 分支创建后，开始将内容合并到主分支，并在准备就绪后进行回溯合并。</li></ul>",6)])])}const u=i(o,[["render",n]]);export{d as __pageData,u as default};
